1	/**
2	 * Plans of Action (POA) routes.
3	 * CRUD for student plans of action at a location.
4	 *
5	 * Routes:
6	 *   GET  /locations/:locationId/poa                      - List all POAs at a location
7	 *   GET  /locations/:locationId/students/:studentId/poa  - List POAs for a student
8	 *   POST /locations/:locationId/students/:studentId/poa  - Create a POA for a student
9	 *   PUT  /locations/:locationId/students/:studentId/poa/:poaId  - Update a POA
10	 *   DELETE /locations/:locationId/students/:studentId/poa/:poaId - Delete a POA
11	 */
12	
13	import { formatErrorForUser } from '@/lib/errors/format-error-for-user';
14	import { plansOfActionRepository } from '@/repositories/mvp-v2.repository.impl';
15	import { isUuid, resolveOrgIdFromSession } from '@/server/helpers';
16	import { type AuthUser, requireAuth } from '@/server/middleware/auth';
17	import { Hono } from 'hono';
18	
19	export const poa = new Hono<{ Variables: { authUser?: AuthUser } }>();
20	
21	function parseUuidCsv(value: string | undefined): string[] | null {
22	  if (!value) return [];
23	  const ids = value
24	    .split(',')
25	    .map((id) => id.trim())
26	    .filter(Boolean);
27	  return ids.every(isUuid) ? [...new Set(ids)] : null;
28	}
29	
30	/**
31	 * GET /locations/:locationId/poa
32	 * List all POA modules for all students at a location.
33	 * Used by POA badge display on training dashboard student cards.
34	 */
35	poa.get('/locations/:locationId/poa', requireAuth(), async (c) => {
36	  const locationId = c.req.param('locationId') ?? '';
37	  const authUser = c.get('authUser') as AuthUser;
38	  if (!isUuid(locationId)) return c.json({ error: 'Invalid id' }, 400);
39	  const studentIds = parseUuidCsv(c.req.query('studentIds'));
40	  if (studentIds === null) {
41	    return c.json({ error: 'Invalid studentIds query param' }, 400);
42	  }
43	  try {
44	    const orgId = await resolveOrgIdFromSession(authUser, c);
45	    if (!orgId) return c.json({ error: 'Could not resolve organization' }, 403);
46	    const modules =
47	      studentIds.length > 0
48	        ? await plansOfActionRepository.findByStudents(
49	            orgId,
50	            locationId,
51	            studentIds,
52	          )
53	        : await plansOfActionRepository.findByLocation(orgId, locationId);
54	    return c.json({ modules });
55	  } catch (err: unknown) {
56	    const structured = formatErrorForUser(err, {
57	      feature: 'POA',
58	      actor: (c.get('authUser') as AuthUser | undefined)?.id,
59	    });
60	    return c.json(
61	      {
62	        error: structured.message,
63	        reference_id: structured.reference_id,
64	        retry_safe: structured.retry_safe,
65	      },
66	      500,
67	    );
68	  }
69	});
70	
71	/**
72	 * GET /locations/:locationId/students/:studentId/poa
73	 * List all POA modules for a specific student.
74	 */
75	poa.get(
76	  '/locations/:locationId/students/:studentId/poa',
77	  requireAuth(),
78	  async (c) => {
79	    const locationId = c.req.param('locationId') ?? '';
80	    const studentId = c.req.param('studentId') ?? '';
81	    const authUser = c.get('authUser') as AuthUser;
82	    if (!isUuid(locationId) || !isUuid(studentId))
83	      return c.json({ error: 'Invalid id' }, 400);
84	    try {
85	      const orgId = await resolveOrgIdFromSession(authUser, c);
86	      if (!orgId)
87	        return c.json({ error: 'Could not resolve organization' }, 403);
88	      const modules = await plansOfActionRepository.findByStudent(
89	        orgId,
90	        locationId,
91	        studentId,
92	      );
93	      return c.json({ modules });
94	    } catch (err: unknown) {
95	      const structured = formatErrorForUser(err, {
96	        feature: 'POA',
97	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
98	      });
99	      return c.json(
100	        {
101	          error: structured.message,
102	          reference_id: structured.reference_id,
103	          retry_safe: structured.retry_safe,
104	        },
105	        500,
106	      );
107	    }
108	  },
109	);
110	
111	/**
112	 * POST /locations/:locationId/students/:studentId/poa
113	 * Create a new POA module for a student.
114	 */
115	poa.post(
116	  '/locations/:locationId/students/:studentId/poa',
117	  requireAuth(),
118	  async (c) => {
119	    const locationId = c.req.param('locationId') ?? '';
120	    const studentId = c.req.param('studentId') ?? '';
121	    const authUser = c.get('authUser') as AuthUser;
122	    if (!isUuid(locationId) || !isUuid(studentId))
123	      return c.json({ error: 'Invalid id' }, 400);
124	    try {
125	      const orgId = await resolveOrgIdFromSession(authUser, c);
126	      if (!orgId)
127	        return c.json({ error: 'Could not resolve organization' }, 403);
128	      const body = (await c.req.json()) as Record<string, unknown>;
129	      const module = await plansOfActionRepository.create(
130	        orgId,
131	        locationId,
132	        studentId,
133	        body,
134	      );
135	      return c.json({ module }, 201);
136	    } catch (err: unknown) {
137	      const structured = formatErrorForUser(err, {
138	        feature: 'POA',
139	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
140	      });
141	      return c.json(
142	        {
143	          error: structured.message,
144	          reference_id: structured.reference_id,
145	          retry_safe: structured.retry_safe,
146	        },
147	        500,
148	      );
149	    }
150	  },
151	);
152	
153	/**
154	 * PUT /locations/:locationId/students/:studentId/poa/:poaId
155	 * Update an existing POA module.
156	 */
157	poa.put(
158	  '/locations/:locationId/students/:studentId/poa/:poaId',
159	  requireAuth(),
160	  async (c) => {
161	    const poaId = c.req.param('poaId') ?? '';
162	    const authUser = c.get('authUser') as AuthUser;
163	    if (!isUuid(poaId)) return c.json({ error: 'Invalid id' }, 400);
164	    try {
165	      const orgId = await resolveOrgIdFromSession(authUser, c);
166	      if (!orgId)
167	        return c.json({ error: 'Could not resolve organization' }, 403);
168	      const body = (await c.req.json()) as Record<string, unknown>;
169	      const module = await plansOfActionRepository.update(orgId, poaId, body);
170	      if (!module) return c.json({ error: 'Not found' }, 404);
171	      return c.json({ module });
172	    } catch (err: unknown) {
173	      const structured = formatErrorForUser(err, {
174	        feature: 'POA',
175	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
176	      });
177	      return c.json(
178	        {
179	          error: structured.message,
180	          reference_id: structured.reference_id,
181	          retry_safe: structured.retry_safe,
182	        },
183	        500,
184	      );
185	    }
186	  },
187	);
188	
189	/**
190	 * DELETE /locations/:locationId/students/:studentId/poa/:poaId
191	 * Delete a POA module.
192	 */
193	poa.delete(
194	  '/locations/:locationId/students/:studentId/poa/:poaId',
195	  requireAuth(),
196	  async (c) => {
197	    const poaId = c.req.param('poaId') ?? '';
198	    const authUser = c.get('authUser') as AuthUser;
199	    if (!isUuid(poaId)) return c.json({ error: 'Invalid id' }, 400);
200	    try {
201	      const orgId = await resolveOrgIdFromSession(authUser, c);
202	      if (!orgId)
203	        return c.json({ error: 'Could not resolve organization' }, 403);
204	      await plansOfActionRepository.delete(orgId, poaId);
205	      return c.json({ success: true });
206	    } catch (err: unknown) {
207	      const structured = formatErrorForUser(err, {
208	        feature: 'POA',
209	        actor: (c.get('authUser') as AuthUser | undefined)?.id,
210	      });
211	      return c.json(
212	        {
213	          error: structured.message,
214	          reference_id: structured.reference_id,
215	          retry_safe: structured.retry_safe,
216	        },
217	        500,
218	      );
219	    }
220	  },
221	);
