1	/**
2	 * T&C Routes — Terms & Conditions acceptance flow
3	 *
4	 * Endpoints for checking acceptance status, accepting T&C on behalf of a school,
5	 * and super-admin publishing/history.
6	 *
7	 * Existing T&C CRUD endpoints (GET/POST /tc/versions, GET/POST /tc/agreements)
8	 * remain in routes-schools.ts. These new endpoints add the acceptance flow.
9	 */
10	
11	import { db } from '@/lib/db';
12	import { formatErrorForUser } from '@/lib/errors/format-error-for-user';
13	import * as schema from '@/lib/schema';
14	import { tcRepository } from '@/repositories/mvp-v2.repository.impl';
15	import {
16	  resolveOrgIdFromSession,
17	  resolveOrgIdFromUserId,
18	} from '@/server/helpers';
19	import {
20	  requireAdmin,
21	  requireAuth,
22	  requireSuperAdmin,
23	} from '@/server/middleware/auth';
24	import type { AuthUser } from '@/server/middleware/auth';
25	import { and, desc, eq } from 'drizzle-orm';
26	import { Hono } from 'hono';
27	
28	const tc = new Hono<{
29	  Variables: { authUser?: AuthUser; managedSchoolId?: string };
30	}>();
31	
32	// ═══════════════════════════════════════════════════════════════════════════
33	// GET /tc/current — Returns the latest published (active) T&C version
34	// ═══════════════════════════════════════════════════════════════════════════
35	tc.get('/tc/current', requireAuth(), async (c) => {
36	  try {
37	    const [current] = await db
38	      .select()
39	      .from(schema.tcVersions)
40	      .where(eq(schema.tcVersions.isActive, true))
41	      .orderBy(desc(schema.tcVersions.publishedAt))
42	      .limit(1);
43	
44	    if (!current) {
45	      return c.json({ version: null });
46	    }
47	
48	    return c.json({
49	      version: {
50	        id: current.id,
51	        version: current.version,
52	        content: current.content,
53	        publishedAt: current.publishedAt?.toISOString() ?? '',
54	        isActive: current.isActive,
55	      },
56	    });
57	  } catch (err: unknown) {
58	    const structured = formatErrorForUser(err, {
59	      feature: 'TC',
60	      actor: (c.get('authUser') as AuthUser | undefined)?.id,
61	    });
62	    return c.json(
63	      {
64	        error: structured.message,
65	        reference_id: structured.reference_id,
66	        retry_safe: structured.retry_safe,
67	      },
68	      500,
69	    );
70	  }
71	});
72	
73	// ═══════════════════════════════════════════════════════════════════════════
74	// GET /tc/acceptance-status — Check if the current user's school has accepted
75	// ═══════════════════════════════════════════════════════════════════════════
76	tc.get('/tc/acceptance-status', requireAuth(), async (c) => {
77	  try {
78	    const authUser = c.get('authUser') as AuthUser;
79	    const orgId = await resolveOrgIdFromSession(authUser, c);
80	
81	    // Get the current active T&C version
82	    const [currentVersion] = await db
83	      .select()
84	      .from(schema.tcVersions)
85	      .where(eq(schema.tcVersions.isActive, true))
86	      .orderBy(desc(schema.tcVersions.publishedAt))
87	      .limit(1);
88	
89	    if (!currentVersion) {
90	      // No T&C published yet — everyone is accepted
91	      return c.json({
92	        accepted: true,
93	        currentVersion: null,
94	        acceptedVersion: null,
95	        gracePeriodEndsAt: null,
96	        daysRemaining: null,
97	      });
98	    }
99	
100	    // Check if any admin from this school has accepted the current version
101	    let accepted = false;
102	    let acceptedVersion: string | null = null;
103	
104	    if (orgId) {
105	      const [agreement] = await db
106	        .select()
107	        .from(schema.tcAgreements)
108	        .where(
109	          and(
110	            eq(schema.tcAgreements.flightSchoolId, orgId),
111	            eq(schema.tcAgreements.tcVersionId, currentVersion.id),
112	          ),
113	        )
114	        .limit(1);
115	
116	      if (agreement) {
117	        accepted = true;
118	        acceptedVersion = currentVersion.version;
119	      }
120	    }
121	
122	    // If not accepted by school, check if the individual user accepted
123	    // (handles super_admin users who may not have a school context)
124	    if (!accepted) {
125	      // Find the app user ID for this auth user
126	      const appUserId = await tcRepository.findUserIdByEmail(authUser.email);
127	      if (appUserId) {
128	        const [userAgreement] = await db
129	          .select()
130	          .from(schema.tcAgreements)
131	          .where(
132	            and(
133	              eq(schema.tcAgreements.userId, appUserId),
134	              eq(schema.tcAgreements.tcVersionId, currentVersion.id),
135	            ),
136	          )
137	          .limit(1);
138	
139	        if (userAgreement) {
140	          accepted = true;
141	          acceptedVersion = currentVersion.version;
142	        }
143	      }
144	    }
145	
146	    // Calculate grace period: 7 days from when the version was published
147	    const publishedAt = currentVersion.publishedAt
148	      ? new Date(currentVersion.publishedAt)
149	      : new Date();
150	    const gracePeriodEndsAt = new Date(
151	      publishedAt.getTime() + 7 * 24 * 60 * 60 * 1000,
152	    );
153	    const now = new Date();
154	    const daysRemaining = accepted
155	      ? null
156	      : Math.max(
157	          0,
158	          Math.ceil(
159	            (gracePeriodEndsAt.getTime() - now.getTime()) /
160	              (24 * 60 * 60 * 1000),
161	          ),
162	        );
163	
164	    return c.json({
165	      accepted,
166	      currentVersion: currentVersion.version,
167	      acceptedVersion,
168	      gracePeriodEndsAt: accepted ? null : gracePeriodEndsAt.toISOString(),
169	      daysRemaining,
170	    });
171	  } catch (err: unknown) {
172	    const structured = formatErrorForUser(err, {
173	      feature: 'TC',
174	      actor: (c.get('authUser') as AuthUser | undefined)?.id,
175	    });
176	    return c.json(
177	      {
178	        error: structured.message,
179	        reference_id: structured.reference_id,
180	        retry_safe: structured.retry_safe,
181	      },
182	      500,
183	    );
184	  }
185	});
186	
187	// ═══════════════════════════════════════════════════════════════════════════
188	// POST /tc/accept — Accept the current T&C on behalf of the school
189	// Only school admins can accept.
190	// ═══════════════════════════════════════════════════════════════════════════
191	tc.post('/tc/accept', requireAdmin(), async (c) => {
192	  try {
193	    const authUser = c.get('authUser') as AuthUser;
194	    const orgId = await resolveOrgIdFromSession(authUser, c);
195	
196	    // Get current active version
197	    const [currentVersion] = await db
198	      .select()
199	      .from(schema.tcVersions)
200	      .where(eq(schema.tcVersions.isActive, true))
201	      .orderBy(desc(schema.tcVersions.publishedAt))
202	      .limit(1);
203	
204	    if (!currentVersion) {
205	      return c.json({ error: 'No active T&C version found' }, 404);
206	    }
207	
208	    // Resolve the app user ID
209	    const appUserId = await tcRepository.findUserIdByEmail(authUser.email);
210	    if (!appUserId) {
211	      return c.json({ error: 'Could not resolve user ID' }, 400);
212	    }
213	
214	    // Scope the acceptance: prefer the session-resolved org (covers super_admin
215	    // acting on a managed school), falling back to the accepting user's own
216	    // flight school so the record is never written NULL-scoped. School-less
217	    // users (e.g. platform super_admin with no managed school) remain null.
218	    const agreementSchoolId =
219	      orgId ?? (await resolveOrgIdFromUserId(appUserId));
220	
221	    // Create the agreement record
222	    const [inserted] = await db
223	      .insert(schema.tcAgreements)
224	      .values({
225	        userId: appUserId,
226	        flightSchoolId: agreementSchoolId ?? undefined,
227	        tcVersionId: currentVersion.id,
228	        agreedAt: new Date(),
229	      })
230	      .returning();
231	
232	    // If the school was in Pending status, activate it
233	    if (orgId) {
234	      await db
235	        .update(schema.flightSchools)
236	        .set({ status: 'Active' })
237	        .where(
238	          and(
239	            eq(schema.flightSchools.id, orgId),
240	            eq(schema.flightSchools.status, 'Pending'),
241	          ),
242	        );
243	    }
244	
245	    return c.json({
246	      accepted: true,
247	      agreement: inserted
248	        ? {
249	            id: inserted.id,
250	            userId: inserted.userId,
251	            tcVersionId: inserted.tcVersionId,
252	            agreedAt: inserted.agreedAt?.toISOString() ?? '',
253	          }
254	        : null,
255	    });
256	  } catch (err: unknown) {
257	    const structured = formatErrorForUser(err, {
258	      feature: 'TC',
259	      actor: (c.get('authUser') as AuthUser | undefined)?.id,
260	    });
261	    return c.json(
262	      {
263	        error: structured.message,
264	        reference_id: structured.reference_id,
265	        retry_safe: structured.retry_safe,
266	      },
267	      500,
268	    );
269	  }
270	});
271	
272	// ═══════════════════════════════════════════════════════════════════════════
273	// GET /tc/history — Lists all T&C versions with acceptance stats (super admin)
274	// ═══════════════════════════════════════════════════════════════════════════
275	tc.get('/tc/history', requireSuperAdmin(), async (c) => {
276	  try {
277	    // Get all versions
278	    const versions = await db
279	      .select()
280	      .from(schema.tcVersions)
281	      .orderBy(desc(schema.tcVersions.publishedAt));
282	
283	    // Get all agreements
284	    const agreements = await db.select().from(schema.tcAgreements);
285	
286	    // Get all schools for stats
287	    const schools = await db
288	      .select({ id: schema.flightSchools.id, name: schema.flightSchools.name })
289	      .from(schema.flightSchools);
290	
291	    const versionStats = versions.map((v) => {
292	      const versionAgreements = agreements.filter(
293	        (a) => a.tcVersionId === v.id,
294	      );
295	      const acceptedSchoolIds = new Set(
296	        versionAgreements.map((a) => a.flightSchoolId).filter(Boolean),
297	      );
298	
299	      return {
300	        id: v.id,
301	        version: v.version,
302	        content: v.content,
303	        isActive: v.isActive,
304	        publishedAt: v.publishedAt?.toISOString() ?? '',
305	        totalAgreements: versionAgreements.length,
306	        schoolsAccepted: acceptedSchoolIds.size,
307	        totalSchools: schools.length,
308	      };
309	    });
310	
311	    return c.json({ versions: versionStats });
312	  } catch (err: unknown) {
313	    const structured = formatErrorForUser(err, {
314	      feature: 'TC',
315	      actor: (c.get('authUser') as AuthUser | undefined)?.id,
316	    });
317	    return c.json(
318	      {
319	        error: structured.message,
320	        reference_id: structured.reference_id,
321	        retry_safe: structured.retry_safe,
322	      },
323	      500,
324	    );
325	  }
326	});
327	
328	// ═══════════════════════════════════════════════════════════════════════════
329	// POST /tc/publish — Publish a new T&C version (super admin)
330	// Sets gracePeriodEndsAt = now + 7 days for all schools that haven't accepted.
331	// ═══════════════════════════════════════════════════════════════════════════
332	tc.post('/tc/publish', requireSuperAdmin(), async (c) => {
333	  try {
334	    const body = (await c.req.json()) as {
335	      version: string;
336	      content: string;
337	    };
338	
339	    if (!body.version?.trim()) {
340	      return c.json({ error: 'version is required' }, 400);
341	    }
342	    if (!body.content?.trim()) {
343	      return c.json(
344	        {
345	          error:
346	            'content is required — users must be able to read the T&C before agreeing',
347	        },
348	        400,
349	      );
350	    }
351	
352	    // Publish using the existing repository method (deactivates old, inserts new)
353	    const inserted = await tcRepository.publishVersion(
354	      body.version,
355	      body.content,
356	    );
357	
358	    return c.json({
359	      version: {
360	        id: inserted.id,
361	        version: inserted.version,
362	        publishedAt: inserted.publishedAt?.toISOString() ?? '',
363	        isActive: inserted.isActive,
364	        gracePeriodEndsAt: new Date(
365	          Date.now() + 7 * 24 * 60 * 60 * 1000,
366	        ).toISOString(),
367	      },
368	    });
369	  } catch (err: unknown) {
370	    const structured = formatErrorForUser(err, {
371	      feature: 'TC',
372	      actor: (c.get('authUser') as AuthUser | undefined)?.id,
373	    });
374	    return c.json(
375	      {
376	        error: structured.message,
377	        reference_id: structured.reference_id,
378	        retry_safe: structured.retry_safe,
379	      },
380	      500,
381	    );
382	  }
383	});
384	
385	export { tc };
