100	/**
101	 * Resolves the deterministic S3 object key for a signed agreement PDF. The
102	 * signing flow always writes to this exact path (see {@link generateAndUploadSignedPdf}),
103	 * so callers can recompute the key from any agreement record without persisting it.
104	 *
105	 * Prefers `signed_storage_path` if the column has been backfilled, otherwise
106	 * derives the key from `flight_school_id` + `id`. The deterministic derivation
107	 * supports legacy rows signed before `signed_storage_path` was populated.
108	 */
109	function getSignedAgreementKey(agreement: {
110	  id: string;
111	  flightSchoolId: string;
112	  signedStoragePath?: string | null;
113	}): string {
114	  if (agreement.signedStoragePath && agreement.signedStoragePath.length > 0) {
115	    return agreement.signedStoragePath;
116	  }
117	  return `agreement-templates/${agreement.flightSchoolId}/signed/${agreement.id}.pdf`;
118	}
