140	 *
141	 * Allowed when:
142	 *   - `super_admin` — cross-school platform role
143	 *   - school admin: `users.role = 'admin'` AND `users.flight_school_id = agreement.flight_school_id`,
144	 *     looked up by **email** (Better Auth `user.id` and Hilo `users.id` are
145	 *     different namespaces, so id-keyed joins never match in production)
146	 *   - location admin: a `team_members` row matching the user's email AND that
147	 *     team member is mapped to `agreement.location_id` via `team_member_locations`
148	 *   - the student themselves: the email-resolved Hilo `users.id` equals
149	 *     `agreement.student_id`
150	 *   - any user that actually signed this agreement: matched against
151	 *     `agreement_signatures.signer_email` or `signer_user_id`
152	 *
153	 * Returns the matched reason on allow and `denied_no_match` on deny. Throws
154	 * on connection-class DB failures so a Neon outage cannot be silently
155	 * mistaken for "not authorized".
156	 */
157	async function canAccessAgreement(
158	  authUser: AuthUser,
159	  agreement: typeof schema.studentAgreements.$inferSelect,
160	): Promise<
161	  | { allow: true; reason: Exclude<AgreementAccessReason, 'denied_no_match'> }
162	  | { allow: false; reason: 'denied_no_match' }
163	> {
164	  if (authUser.role === 'super_admin') {
165	    return { allow: true, reason: 'super_admin' };
166	  }
167	
168	  const email = authUser.email.toLowerCase();
169	
170	  // School admin / student-self: both live in `users`, keyed by email.
171	  // We fetch role + flight_school_id + id in one query so we can branch on
172	  // whichever rule matches first without a second round-trip.
173	  const [appUser] = await db
174	    .select({
175	      id: schema.users.id,
176	      role: schema.users.role,
177	      flightSchoolId: schema.users.flightSchoolId,
178	    })
179	    .from(schema.users)
180	    .where(eq(schema.users.email, email))
181	    .limit(1);
182	
183	  if (
184	    appUser?.role === 'admin' &&
185	    appUser.flightSchoolId === agreement.flightSchoolId
186	  ) {
187	    return { allow: true, reason: 'school_admin' };
188	  }
189	  if (appUser?.id === agreement.studentId) {
190	    return { allow: true, reason: 'student_self' };
191	  }
192	
193	  // Location admin: stored in `team_members`, scoped per location via
194	  // `team_member_locations`. Both rows must match — same school AND the
195	  // team member is assigned to the agreement's specific location.
196	  const [locationAdmin] = await db
197	    .select({ memberId: schema.teamMembers.id })
198	    .from(schema.teamMembers)
199	    .innerJoin(
200	      schema.teamMemberLocations,
201	      eq(schema.teamMemberLocations.teamMemberId, schema.teamMembers.id),
202	    )
203	    .where(
204	      and(
205	        eq(schema.teamMembers.email, email),
206	        eq(schema.teamMembers.flightSchoolId, agreement.flightSchoolId),
207	        eq(schema.teamMemberLocations.locationId, agreement.locationId),
208	      ),
209	    )
210	    .limit(1);
211	  if (locationAdmin) {
212	    return { allow: true, reason: 'location_admin' };
213	  }
214	
215	  // Signer match: anyone who actually signed this agreement (recorded in
216	  // `agreement_signatures`) keeps access even if their school assignment
217	  // changes later. Match on signer_email primarily; fall back to
218	  // signer_user_id for legacy rows that only captured the Hilo user id.
219	  const signerByEmail = await db
220	    .select({ id: schema.agreementSignatures.id })
221	    .from(schema.agreementSignatures)
222	    .where(
223	      and(
224	        eq(schema.agreementSignatures.agreementInstanceId, agreement.id),
225	        eq(schema.agreementSignatures.signerEmail, email),
226	      ),
227	    )
228	    .limit(1);
229	  if (signerByEmail[0]) {
230	    return { allow: true, reason: 'signer' };
231	  }
232	  if (appUser?.id) {
233	    const signerByUserId = await db
234	      .select({ id: schema.agreementSignatures.id })
235	      .from(schema.agreementSignatures)
236	      .where(
237	        and(
238	          eq(schema.agreementSignatures.agreementInstanceId, agreement.id),
239	          eq(schema.agreementSignatures.signerUserId, appUser.id),
240	        ),
241	      )
242	      .limit(1);
243	    if (signerByUserId[0]) {
244	      return { allow: true, reason: 'signer' };
245	    }
246	  }
247	
248	  return { allow: false, reason: 'denied_no_match' };
249	}
