251	/**
252	 * Back-compat shim: keep the old boolean shape for call sites that only need
253	 * the allow/deny decision and don't care about the matched reason.
254	 */
255	async function userCanAccessAgreement(
256	  authUser: AuthUser,
257	  agreement: typeof schema.studentAgreements.$inferSelect,
258	): Promise<boolean> {
259	  return (await canAccessAgreement(authUser, agreement)).allow;
260	}
