262	/**
263	 * Whether the caller may see signingToken/adminSigningToken in an agreement
264	 * LIST response for this location (as opposed to a single record, which goes
265	 * through canAccessAgreement instead — there is no single agreement here to
266	 * check a signer match against).
267	 *
268	 * The list route is location-scoped (requireLocationTenant already confirmed
269	 * the caller belongs to that location's school), so the only question left is
270	 * "is this caller an admin," not "which school." Same admin/location-admin
271	 * lookups as canAccessAgreement, minus the per-agreement student/signer
272	 * checks that don't apply to a list.
273	 *
274	 * A student must never see a peer's signingToken here: the unauthenticated
275	 * POST /sign/:token/submit endpoint accepts signerName from the request body,
276	 * so leaking another student's token lets anyone e-sign as them.
277	 *
278	 * Filters the users lookup by email AND flightSchoolId (not email alone,
279	 * then check): users.email has no unique constraint (users_email_idx is a
280	 * plain index — a legitimate multi-school email holds one row per school,
281	 * same as resolveOrgIdFromEmail assumes), so an email-only `.limit(1)` could
282	 * pick an arbitrary row and falsely deny an admin whose row for THIS school
283	 * isn't the one returned. canAccessAgreement has the same email-only lookup;
284	 * left unchanged here since it's shared by other call sites outside ENGI-235's
285	 * scope — worth its own follow-up ticket.
286	 */
287	async function canViewAgreementTokensForLocation(
288	  authUser: AuthUser,
289	  flightSchoolId: string,
290	  locationId: string,
291	): Promise<boolean> {
292	  if (authUser.role === 'super_admin') return true;
293	
294	  const email = authUser.email.toLowerCase();
295	
296	  const [appUser] = await db
297	    .select({ role: schema.users.role })
298	    .from(schema.users)
299	    .where(
300	      and(
301	        eq(schema.users.email, email),
302	        eq(schema.users.flightSchoolId, flightSchoolId),
303	      ),
304	    )
305	    .limit(1);
306	  if (appUser?.role === 'admin') {
307	    return true;
308	  }
309	
310	  const [locationAdmin] = await db
311	    .select({ memberId: schema.teamMembers.id })
312	    .from(schema.teamMembers)
313	    .innerJoin(
314	      schema.teamMemberLocations,
315	      eq(schema.teamMemberLocations.teamMemberId, schema.teamMembers.id),
316	    )
317	    .where(
318	      and(
319	        eq(schema.teamMembers.email, email),
320	        eq(schema.teamMembers.flightSchoolId, flightSchoolId),
321	        eq(schema.teamMemberLocations.locationId, locationId),
322	      ),
323	    )
324	    .limit(1);
325	
326	  return Boolean(locationAdmin);
327	}
