701	/** GET /schools/:schoolId/agreement-templates/:id/signer-steps
702	 *
703	 * Returns the signer steps row-set used by the field editor's recipient strip.
704	 *
705	 * Self-healing hydration: if the table has no rows for this template but the
706	 * template's signer_workflow JSONB is populated (which happens when the upload
707	 * drawer's "Save & Place Fields" PATCHes /workflow before the editor has ever
708	 * persisted steps), we materialize rows from the JSONB on first read so the
709	 * editor opens with the recipients the admin configured one screen earlier.
710	 * Without this, the editor's strip starts empty and the admin has to re-add
711	 * every recipient — which is the bug described in Asana 1214588596197790.
712	 */
713	agreementsRouter.get(
714	  '/schools/:schoolId/agreement-templates/:id/signer-steps',
715	  requireAuth(),
716	  requireSchoolTenant(),
717	  async (c) => {
718	    const { schoolId, id } = c.req.param();
719	    try {
720	      // Verify template belongs to school AND fetch signer_workflow for hydration
721	      const [template] = await db
722	        .select({
723	          id: schema.agreementTemplates.id,
724	          signerWorkflow: schema.agreementTemplates.signerWorkflow,
725	        })
726	        .from(schema.agreementTemplates)
727	        .where(
728	          and(
729	            eq(schema.agreementTemplates.id, id),
730	            eq(schema.agreementTemplates.flightSchoolId, schoolId),
731	          ),
732	        )
733	        .limit(1);
734	      if (!template) return c.json({ error: 'Template not found' }, 404);
735	
736	      const existing = await db
737	        .select()
738	        .from(schema.agreementSignerSteps)
739	        .where(eq(schema.agreementSignerSteps.agreementId, id))
740	        .orderBy(asc(schema.agreementSignerSteps.position));
741	
742	      if (existing.length > 0) return c.json({ steps: existing });
743	
744	      // Empty table — try hydrating from signer_workflow JSONB
745	      const workflow = template.signerWorkflow as schema.SignerWorkflow | null;
746	      if (
747	        !workflow ||
748	        !Array.isArray(workflow.steps) ||
749	        workflow.steps.length === 0
750	      ) {
751	        return c.json({ steps: [] });
752	      }
753	
754	      const hydrated = workflow.steps
755	        .slice()
756	        .sort((a, b) => a.order - b.order)
757	        .map((step, idx) => {
758	          const isStudent = step.role === 'student';
759	          const roleKey =
760	            step.roleKey ?? (isStudent ? 'student' : 'general_admin');
761	          const colorIdx = idx % schema.SIGNER_STEP_COLORS.length;
762	          return {
763	            agreementId: id,
764	            position: step.order,
765	            roleKey,
766	            label: step.label,
767	            designatedUserId: step.signerUserId ?? null,
768	            recipientEmail: step.signerEmail ?? null,
769	            // Admin steps with no specific user can be signed by any role-holder
