8	/** Does the caller hold a live membership row in this school? */
9	async function isMemberOfSchool(
10	  flightSchoolId: string,
11	  email: string,
12	): Promise<boolean> {
13	  // users.email is normalized lowercase on write; team_members.email is not.
14	  // Both conventions copied from resolveOrgIdFromEmail (helpers.ts).
15	  const [user] = await db
16	    .select({ id: schema.users.id })
17	    .from(schema.users)
18	    .where(
19	      and(
20	        eq(schema.users.email, email),
21	        eq(schema.users.flightSchoolId, flightSchoolId),
22	        isNull(schema.users.deletedAt),
23	      ),
24	    )
25	    .limit(1);
26	  if (user) return true;
27	
28	  // Location Admins live in team_members, not users (helpers.ts:207-209).
29	  const [member] = await db
30	    .select({ id: schema.teamMembers.id })
31	    .from(schema.teamMembers)
32	    .where(
33	      and(
34	        sql`lower(${schema.teamMembers.email}) = ${email}`,
35	        eq(schema.teamMembers.flightSchoolId, flightSchoolId),
36	      ),
37	    )
38	    .limit(1);
39	  return Boolean(member);
40	}
