42	/**
43	 * Blocks cross-tenant access on `/locations/:locationId/...` routes.
44	 *
45	 * These routes derived their tenant from the client-supplied path param and
46	 * never compared it to the session, so any authenticated user could read
47	 * another school's data by substituting a foreign locationId (TD-15).
48	 *
49	 * Deliberately does NOT use `verifyLocationAccess`: that helper resolves the
50	 * caller's org via `resolveOrgIdFromEmail`, which collapses a multi-school
51	 * email to one deterministic PRIMARY row (helpers.ts:200-204) and so refuses a
52	 * legitimately multi-school user their other school. Checking membership
53	 * directly is both simpler and correct for those callers.
54	 *
55	 * Register it AFTER `requireAuth()` — it reads the authUser that sets:
56	 *
57	 * @example
58	 * reports.get(path, requireAuth(), requireLocationTenant(), handler);
59	 *
60	 * Not usable as `app.use('*', ...)`: routers are mounted via
61	 * `app.route('/', sub)`, which flattens a sub-app wildcard across every other
62	 * router — and `use()` runs before route-level `requireAuth()`, so `authUser`
63	 * would not be set yet.
64	 */
65	export function requireLocationTenant() {
66	  return async (c: Context, next: Next): Promise<Response | undefined> => {
67	    const locationId = c.req.param('locationId');
68	
69	    // A non-UUID matches no location, so nothing can leak. Defer to the
70	    // handler's existing `{ error: 'Invalid location ID' }, 400`.
71	    if (!locationId || !isUuid(locationId)) {
72	      await next();
73	      return undefined;
74	    }
75	
76	    const authUser = c.get('authUser') as AuthUser | undefined;
77	    if (!authUser) return c.json({ error: 'Unauthorized' }, 401);
78	
79	    const flightSchoolId = await resolveLocationFlightSchoolId(locationId);
80	
81	    // One opaque 403 for "no such location" and "not your school" alike, so the
82	    // response cannot be used to enumerate location UUIDs.
83	    const allowed =
84	      Boolean(flightSchoolId) &&
85	      (authUser.role === 'super_admin' ||
86	        (await isMemberOfSchool(
87	          flightSchoolId as string,
88	          authUser.email.toLowerCase(),
89	        )));
90	
91	    if (!allowed) return c.json({ error: 'Forbidden' }, 403);
92	
93	    await next();
94	    return undefined;
95	  };
96	}
97	
98	/**
99	 * Blocks cross-tenant access on `/schools/:schoolId/...` routes.
100	 *
101	 * Same problem as `requireLocationTenant` (ENGI-235): these routes derived
102	 * their tenant from the client-supplied `:schoolId` path param and never
103	 * compared it to the session. Simpler than the location variant — `schoolId`
104	 * *is* the tenant id directly, so there is no location-to-school lookup and
105	 * no "unknown location" ambiguity to fold into the opaque 403; the only
106	 * failure mode is "caller isn't a member of this school."
107	 *
108	 * Unlike `requireLocationTenant`, this rejects a non-UUID `schoolId` itself
109	 * (400) rather than deferring to the handler: only 1 of the 10
110	 * `/schools/:schoolId/agreement-templates*` routes validates the id's shape,
111	 * so there is no handler-level 400 contract to defer to for the other 9.
112	 *
113	 * Register it AFTER `requireAuth()` — it reads the authUser that sets:
114	 *
115	 * @example
116	 * agreementsRouter.get(path, requireAuth(), requireSchoolTenant(), handler);
117	 *
118	 * Not usable as `app.use('*', ...)` — see `requireLocationTenant`'s doc
119	 * comment for why (route-level middleware ordering, not global).
120	 */
121	export function requireSchoolTenant() {
122	  return async (c: Context, next: Next): Promise<Response | undefined> => {
123	    const schoolId = c.req.param('schoolId');
124	
125	    if (!schoolId || !isUuid(schoolId)) {
126	      return c.json({ error: 'Invalid school ID' }, 400);
127	    }
128	
129	    const authUser = c.get('authUser') as AuthUser | undefined;
130	    if (!authUser) return c.json({ error: 'Unauthorized' }, 401);
131	
132	    const allowed =
133	      authUser.role === 'super_admin' ||
134	      (await isMemberOfSchool(schoolId, authUser.email.toLowerCase()));
135	
136	    if (!allowed) return c.json({ error: 'Forbidden' }, 403);
137	
138	    await next();
139	    return undefined;
140	  };
141	}
