146	function SignatureCanvas({ onCapture, onClear, hasSig }: SignatureCanvasProps) {
147	  const canvasRef = useRef<HTMLCanvasElement>(null);
148	  const drawing = useRef(false);
149	  const lastPos = useRef<{ x: number; y: number } | null>(null);
150	
151	  function getPos(e: React.MouseEvent | React.TouchEvent) {
152	    const canvas = canvasRef.current;
153	    if (!canvas) return null;
154	    const rect = canvas.getBoundingClientRect();
155	    if ('touches' in e) {
156	      const touch = e.touches[0];
157	      if (!touch) return null;
158	      return {
159	        x: touch.clientX - rect.left,
160	        y: touch.clientY - rect.top,
161	      };
162	    }
163	    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
164	  }
165	
166	  function startDraw(e: React.MouseEvent | React.TouchEvent) {
167	    drawing.current = true;
168	    lastPos.current = getPos(e);
169	  }
170	
171	  function draw(e: React.MouseEvent | React.TouchEvent) {
172	    if (!drawing.current || !lastPos.current) return;
173	    const canvas = canvasRef.current;
174	    if (!canvas) return;
175	    const ctx = canvas.getContext('2d');
176	    if (!ctx) return;
177	    const pos = getPos(e);
178	    if (!pos) return;
179	    ctx.beginPath();
180	    ctx.moveTo(lastPos.current.x, lastPos.current.y);
181	    ctx.lineTo(pos.x, pos.y);
182	    ctx.strokeStyle = '#1e293b';
183	    ctx.lineWidth = 2;
184	    ctx.lineCap = 'round';
185	    ctx.stroke();
186	    lastPos.current = pos;
187	  }
188	
189	  function endDraw() {
190	    drawing.current = false;
191	    lastPos.current = null;
192	    const canvas = canvasRef.current;
193	    if (canvas) {
194	      onCapture(canvas.toDataURL('image/png'));
195	    }
196	  }
197	
198	  function clearCanvas() {
199	    const canvas = canvasRef.current;
200	    if (!canvas) return;
201	    const ctx = canvas.getContext('2d');
202	    if (ctx) {
203	      ctx.clearRect(0, 0, canvas.width, canvas.height);
204	    }
205	    onClear();
206	  }
207	
208	  return (
209	    <div className="flex flex-col items-center gap-2">
210	      <canvas
211	        ref={canvasRef}
212	        width={400}
213	        height={120}
214	        className="border-2 border-dashed border-slate-300 rounded-lg bg-white touch-none cursor-crosshair"
215	        onMouseDown={startDraw}
216	        onMouseMove={draw}
217	        onMouseUp={endDraw}
218	        onMouseLeave={endDraw}
219	        onTouchStart={startDraw}
220	        onTouchMove={draw}
221	        onTouchEnd={endDraw}
222	      />
223	      <div className="flex gap-2">
224	        <button
225	          type="button"
226	          onClick={clearCanvas}
227	          className="px-3 py-1 text-xs border border-slate-200 rounded-md text-slate-600 hover:bg-slate-50 transition-colors"
228	        >
229	          Clear
230	        </button>
231	        {hasSig && (
232	          <span className="flex items-center gap-1 text-xs text-emerald-600">
233	            <CheckCircle2 className="w-3.5 h-3.5" /> Signature captured
234	          </span>
235	        )}
236	      </div>
237	    </div>
238	  );
239	}
